const listCDKeysPage = `-- name: ListCDKeysPage :many
SELECT
    c.id,
    c.batch_id,
    c.code_prefix,
    c.code_suffix,
    c.amount,
    c.currency,
    c.status,
    c.created_at,
    c.redeemed_at,
    c.revoked_at,
    r.id AS redemption_id,
    r.user_id AS redemption_user_id,
    u.email AS redemption_user_email,
    u.display_name AS redemption_user_display_name,
    r.ledger_entry_id AS redemption_ledger_entry_id,
    r.redeemed_at AS redemption_redeemed_at,
    COUNT(*) OVER () AS total_count
FROM cdkeys c
LEFT JOIN cdkey_redemptions r ON r.cdkey_id = c.id
LEFT JOIN users u ON u.id = r.user_id
WHERE (cardinality($1::text[]) = 0 OR c.status = ANY($1::text[]))
  AND ($2::numeric IS NULL OR c.amount = $2::numeric)
  AND ($3::uuid IS NULL OR c.batch_id = $3::uuid)
  AND ($4::text IS NULL OR (
      c.code_prefix ILIKE '%' || $4::text || '%'
      OR c.code_suffix ILIKE '%' || $4::text || '%'
      OR c.batch_id::text ILIKE '%' || $4::text || '%'
      OR COALESCE(u.email, '') ILIKE '%' || $4::text || '%'
      OR COALESCE(r.user_id::text, '') ILIKE '%' || $4::text || '%'
  ))
  AND ($5::timestamptz IS NULL OR c.created_at >= $5::timestamptz)
  AND ($6::timestamptz IS NULL OR c.created_at < $6::timestamptz)
ORDER BY
  CASE WHEN COALESCE($7::text, 'created_at') IN ('', 'created_at') AND COALESCE($8::bool, true) THEN c.created_at END DESC NULLS LAST,
  CASE WHEN COALESCE($7::text, 'created_at') IN ('', 'created_at') AND NOT COALESCE($8::bool, true) THEN c.created_at END ASC NULLS LAST,
  CASE WHEN $7::text = 'amount' AND COALESCE($8::bool, false) THEN c.amount END DESC NULLS LAST,
  CASE WHEN $7::text = 'amount' AND NOT COALESCE($8::bool, false) THEN c.amount END ASC NULLS LAST,
  CASE WHEN $7::text = 'status' AND COALESCE($8::bool, false) THEN c.status END DESC NULLS LAST,
  CASE WHEN $7::text = 'status' AND NOT COALESCE($8::bool, false) THEN c.status END ASC NULLS LAST,
  CASE WHEN COALESCE($7::text, 'created_at') IN ('', 'created_at') AND COALESCE($8::bool, true) THEN c.id END DESC,
  CASE WHEN COALESCE($7::text, 'created_at') IN ('', 'created_at') AND NOT COALESCE($8::bool, true) THEN c.id END ASC,
  c.id DESC
LIMIT $10 OFFSET $9
`

