const revokeCDKeyIfUnused = `-- name: RevokeCDKeyIfUnused :execrows
UPDATE cdkeys
SET status = 'revoked', revoked_at = now()
WHERE id = $1 AND status = 'unused'
`

func (q *Queries) RevokeCDKeyIfUnused(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.Exec(ctx, revokeCDKeyIfUnused, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateConsoleCDKeyRedeemed = `-- name: UpdateConsoleCDKeyRedeemed :execrows

UPDATE cdkeys
SET status = 'redeemed', redeemed_at = $1, revoked_at = NULL
WHERE id = $2 AND status = 'unused'
`

type UpdateConsoleCDKeyRedeemedParams struct {
	RedeemedAt pgtype.Timestamptz
	ID         int64
}

// Console redemption reads/writes are deliberately narrow; no plaintext is returned.
// Keep the Console state transition write-only. In particular, do not use the
// shared Admin-shaped UPDATE ... RETURNING query here: that result includes
// code_plaintext and would unnecessarily bring the redeemable credential into
// the Console process.
func (q *Queries) UpdateConsoleCDKeyRedeemed(ctx context.Context, arg UpdateConsoleCDKeyRedeemedParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateConsoleCDKeyRedeemed, arg.RedeemedAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
